import os, re, glob
D = r"C:\Users\eric_rash\Desktop\DEV\Flint\.claude\worktrees\step1-triage\staging\library\strength-and-conditioning\elite-sports-performance--evans"
for f in sorted(glob.glob(os.path.join(D, "*--*.md"))):
    t = open(f, encoding="utf8").read()
    name = os.path.basename(f)
    paras = re.split(r"\n\s*\n", t)
    issues = []
    for p in paras:
        flat = " ".join(p.split())
        if re.search(r"baseline", flat, re.I):
            if "Eric's baseline:" not in flat and "Eric's review:" not in flat:
                issues.append("NO-LABEL: " + flat[:160])
            for m in re.finditer(r"Eric's baseline(?!:)", flat):
                issues.append("NOCOLON: " + flat[max(0, m.start()-40):m.start()+120])
        for m in re.finditer(r"(own words|own voice|lecturing voice|states directly|in his own)", flat):
            issues.append("VOICE: " + flat[max(0, m.start()-60):m.start()+60])
    body_em = [l for l in t.splitlines() if "\u2014" in l and not l.startswith("**")]
    if body_em:
        issues.append(f"EMDASH-body lines: {len(body_em)}")
    lines = re.findall(r"line \d+", t)
    if lines:
        issues.append("LINE-REFS: " + ", ".join(lines))
    if issues:
        print("==", name)
        for i in issues:
            print("   ", i)

